content.query:
// Headline KPI tiles. One row per tile.
// Requirement (1) "Total number of employees" is the first tile.
//
// PERFORMANCE: Ident is materialized once and read by six toscalar() subqueries.
// Without materialize each toscalar re-scans IdentityInfo; with it they share a
// single cached result. Projection happens before arg_max so the shuffle carries
// 7 columns instead of 56.
// SCOPE: honours the Division parameter, so the tiles agree with every other
// panel instead of silently reporting org-wide numbers under a filtered view.
let Ident = materialize(
    IdentityInfo
    | project TimeGenerated, AccountObjectId, AccountUPN, Department,
              IsAccountEnabled, UserType, AssignedRoles
    | summarize arg_max(TimeGenerated, *) by AccountObjectId
    | extend Department = iif(isempty(Department), "Unmapped", Department)
    | where "{DeptFilter}" == "*" or Department == "{DeptFilter}");
let InScope = Ident | project Principal = tolower(AccountUPN);
let Scoped = "{DeptFilter}" != "*";
let TotalEmployees = toscalar(Ident | where UserType =~ "Member" or isempty(UserType) | count);
let TotalIdent     = toscalar(Ident | count);
let EnabledCount   = toscalar(Ident | where IsAccountEnabled == true | count);
let GuestCount     = toscalar(Ident | where UserType =~ "Guest" | count);
let DeptCount      = toscalar(Ident | where Department != "Unmapped" | distinct Department | count);
let PrivCount      = toscalar(Ident | where array_length(todynamic(AssignedRoles)) > 0 | count);
let AlertUsers     = toscalar(
    SecurityAlert
    | where TimeGenerated {TimeRange}
    | where Entities has "account"
    | project Entities
    | mv-expand E = todynamic(Entities)
    | where tostring(E.Type) =~ "account"
    | extend AcctName = tostring(E.Name), Sfx = tostring(E.UPNSuffix)
    | where isnotempty(AcctName)
    | extend P = tolower(iif(isnotempty(Sfx), strcat(AcctName, "@", Sfx), AcctName))
    | where not(Scoped) or P in (InScope)
    | distinct P | count);
let AnomUsers      = toscalar(
    Anomalies
    | where TimeGenerated {TimeRange} | where RuleStatus == "Production"
    | extend P = tolower(coalesce(iif(isempty(UserPrincipalName), '', UserPrincipalName),
                                  iif(isempty(UserName), '', UserName)))
    | where isnotempty(P)
    | where not(Scoped) or P in (InScope)
    | distinct P | count);
let UebaUsers      = toscalar(
    BehaviorAnalytics
    | where TimeGenerated {TimeRange} | where InvestigationPriority > 0
    | extend P = tolower(coalesce(iif(isempty(UserPrincipalName), '', UserPrincipalName),
                                  iif(isempty(ActorPrincipalName), '', ActorPrincipalName),
                                  iif(isempty(UserName), '', UserName)))
    | where isnotempty(P)
    | where not(Scoped) or P in (InScope)
    | distinct P | count);
let FlaggedUsers   = AlertUsers + AnomUsers + UebaUsers;
let OpenIncidents  = toscalar(SecurityIncident
    | where TimeGenerated {TimeRange}
    | summarize arg_max(TimeGenerated, Status) by IncidentNumber
    | where Status != "Closed" | count);
range Ordinal from 1 to 6 step 1
| extend Metric = case(Ordinal == 1, "Total employees",
                       Ordinal == 2, "Enabled accounts",
                       Ordinal == 3, "Privileged identities",
                       Ordinal == 4, "Users with risk signal",
                       Ordinal == 5, "Departments mapped",
                                     "Open incidents")
| extend Value  = case(Ordinal == 1, TotalEmployees,
                       Ordinal == 2, EnabledCount,
                       Ordinal == 3, PrivCount,
                       Ordinal == 4, FlaggedUsers,
                       Ordinal == 5, DeptCount,
                                     OpenIncidents)
| extend Context= case(Ordinal == 1, strcat(tostring(TotalIdent), " identities / ", tostring(GuestCount), " guest",
                                            iif(Scoped, " / scoped to {DeptFilter}", " / all divisions")),
                       Ordinal == 2, strcat(tostring(TotalIdent - EnabledCount), " disabled or dormant"),
                       Ordinal == 3, "holds one or more directory roles",
                       Ordinal == 4, strcat("UEBA ", tostring(UebaUsers), " / anomaly ", tostring(AnomUsers), " / alert ", tostring(AlertUsers)),
                       Ordinal == 5, "distinct values in IdentityInfo",
                                     "not in a closed state (org-wide)")
| extend Health = case(Ordinal == 4 and Value > 0, "warning",
                       Ordinal == 6 and Value > 0, "warning",
                       Value == 0, "unknown",
                                   "success")
| project Ordinal, Metric, Value, Context, Health
| order by Ordinal asc

// Privileged identities by division AND role -- left panel of the two-panel
// drill-down. Each division contributes one row per directory role, so
// "Internal" expands into the actual roles its privileged users hold rather
// than an opaque "3-4 roles" bucket.
//
// DEPARTMENT CASING: IdentityInfo carries free-text Department straight from
// Entra, and this tenant has both "Internal" and "internal" (likewise
// "External"/"external"). Grouped naively they split into separate rows and
// every division total is understated. Rows are therefore grouped on a
// lower-cased key and displayed using the most common original spelling.
let Ident = materialize(
    IdentityInfo
    | project TimeGenerated, AccountObjectId, AccountUPN, AccountDisplayName,
              Department, JobTitle, AssignedRoles, IsAccountEnabled
    | summarize arg_max(TimeGenerated, *) by AccountObjectId
    | extend Dept = iif(isempty(Department), "Unmapped", Department)
    | extend DeptKey = tolower(Dept));
let DeptCanon =
    Ident
    | summarize Seen = count() by DeptKey, Dept
    | summarize arg_max(Seen, Dept) by DeptKey
    | project DeptKey, Division = Dept;
let Priv =
    Ident
    | where array_length(todynamic(AssignedRoles)) > 0
    | mv-expand RoleRaw = todynamic(AssignedRoles)
    // AssignedRoles may hold plain strings or objects depending on the entity
    // provider. coalesce covers both without assuming a shape.
    | extend Role = coalesce(tostring(RoleRaw.Name),
                             tostring(RoleRaw.roleName),
                             tostring(RoleRaw.DisplayName),
                             tostring(RoleRaw))
    | where isnotempty(Role) and Role != "[]"
    | lookup kind=leftouter DeptCanon on DeptKey
    | extend Division = iif(isempty(Division), Dept, Division);
Priv
| where "{DeptFilter}" == "*" or Division =~ "{DeptFilter}"
| summarize Identities = dcount(AccountObjectId),
            Enabled    = dcountif(AccountObjectId, IsAccountEnabled == true),
            Disabled   = dcountif(AccountObjectId, IsAccountEnabled == false)
    by Division, Role
| extend RowKey = strcat(Division, "||", Role)
| extend Posture = case(Disabled > 0 and Enabled == 0, "All disabled",
                        Disabled > 0,                  "Mixed",
                                                       "All enabled")
| project Division, Role, Identities, Enabled, Disabled, Posture, RowKey
| order by Identities desc, Division asc

// ===== RISK MODEL =====================================================
// Everything the dashboard scores flows from this block. Change a weight here
// and every panel moves together. Nothing else in the workbook hard-codes a
// number, which is what makes the index auditable.
//
// Design principle: the index separates a QUALITY axis (how unusual / how broad)
// from a VOLUME axis (how many). Microsoft's own scores do the same thing --
// InvestigationPriority measures how unusual, not how many -- so the two stay
// visible rather than being blended into one opaque number.
//
// FIELD HYGIENE: the IdentityInfo columns Microsoft lists as unsupported
// (InvestigationPriority, InvestigationPriorityPercentile, EntityRiskScore,
// IsServiceAccount, IsMFARegistered, LastSeenDate, Applications, Tags, UACFlags,
// RelatedAccounts, ServicePrincipals, ExtensionProperty,
// OnPremisesExtensionAttributes) are deliberately NOT referenced.
let W_Ueba    = 25.0;   // UEBA behaviour priority   -- quality
let W_Anomaly = 20.0;   // UEBA anomaly rules        -- quality
let W_Alert   = 25.0;   // analytics-rule alerts     -- volume
let W_Breadth = 20.0;   // kill-chain breadth        -- quality
let W_Blast   = 10.0;   // blast radius / privilege  -- impact
let SevWeight = dynamic({"High": 10, "Medium": 5, "Low": 2, "Informational": 1});
let BandCrit  = 70.0;
let BandHigh  = 45.0;
let BandElev  = 25.0;
//
// PERFORMANCE
//   materialize() on every let that is consumed more than once. Ident is read
//   by Sig_Blast and the final lookup; AlertAccounts by Sig_Alert and
//   TacticRows; AnomalyEvents by Sig_Anomaly and TacticRows. Without
//   materialize each consumer re-scans the source table -- on a directory of
//   this size that is the difference between a dashboard that loads and one
//   that makes a room wait.
//   project-away happens BEFORE arg_max: IdentityInfo has 56 columns and we
//   need 14, and arg_max(TimeGenerated, *) carries every one of them through
//   the shuffle.
let Ident = materialize(
    IdentityInfo
    | project TimeGenerated, AccountObjectId, AccountUPN, AccountDisplayName,
              Department, JobTitle, Manager, City, Country, MailAddress,
              IsAccountEnabled, UserType, UserState, AssignedRoles, BlastRadius
    | summarize arg_max(TimeGenerated, *) by AccountObjectId
    | extend Department = iif(isempty(Department), "Unmapped", Department));
//
// Division scope. One definition, applied to every source below, so the
// Division picker actually drives the whole workbook instead of one panel.
// The "*" short-circuit keeps principals that have no IdentityInfo row when
// no division is selected -- filtering on membership would silently drop them.
let InScope = Ident | where Department == "{DeptFilter}" | project Principal = tolower(AccountUPN);
//
let AlertAccounts = materialize(
    SecurityAlert
    | where TimeGenerated {TimeRange}
    // Cheap string prefilter before the expensive expansion. Entities is a
    // string column, so this runs as a substring scan and discards alerts with
    // no account entity before mv-expand multiplies the row count.
    | where Entities has "account"
    | project TimeGenerated, AlertName, AlertSeverity, Tactics, ProductName, ProviderName, Entities
    | extend Ents = todynamic(Entities)
    | mv-expand Ent = Ents
    | where tostring(Ent.Type) =~ "account"
    | extend AcctName = tostring(Ent.Name), UpnSuffix = tostring(Ent.UPNSuffix)
    | where isnotempty(AcctName)
    | extend Principal = tolower(iif(isnotempty(UpnSuffix), strcat(AcctName, "@", UpnSuffix), AcctName))
    | where "{DeptFilter}" == "*" or Principal in (InScope)
    | project Principal, TimeGenerated, AlertName, AlertSeverity, Tactics, ProductName, ProviderName);
//
let AnomalyEvents = materialize(
    Anomalies
    | where TimeGenerated {TimeRange}
    | where RuleStatus == "Production"
    | extend Principal = tolower(coalesce(iif(isempty(UserPrincipalName), '', UserPrincipalName),
                                          iif(isempty(UserName), '', UserName)))
    | where isnotempty(Principal)
    | where "{DeptFilter}" == "*" or Principal in (InScope)
    | project Principal, TimeGenerated, RuleName, Score, Tactics, Techniques, Description);
//
let UebaEvents = materialize(
    BehaviorAnalytics
    | where TimeGenerated {TimeRange}
    | extend Principal = tolower(coalesce(iif(isempty(UserPrincipalName),  '', UserPrincipalName),
                                          iif(isempty(ActorPrincipalName), '', ActorPrincipalName),
                                          iif(isempty(UserName),           '', UserName)))
    | where isnotempty(Principal)
    | where "{DeptFilter}" == "*" or Principal in (InScope)
    | project Principal, TimeGenerated, ActivityType, ActionType, EventSource,
              InvestigationPriority, ActivityInsights, UsersInsights, DevicesInsights,
              SourceIPAddress, SourceIPLocation);
//
let Sig_Ueba =
    UebaEvents
    | summarize Raw = sum(InvestigationPriority), Peak = max(InvestigationPriority), Events = count() by Principal
    | where Raw > 0
    | extend Points = min_of(W_Ueba, Raw / 4.0), Axis = "Quality"
    | extend Component = "UEBA behaviour priority",
             Detail = strcat(tostring(Events), " scored events / cumulative IP ", tostring(Raw), " / peak ", tostring(Peak))
    | project Principal, Component, Axis, Points, Detail;
//
let Sig_Anomaly =
    AnomalyEvents
    | summarize Raw = sum(Score), Rules = dcount(RuleName), Hits = count() by Principal
    | extend Points = min_of(W_Anomaly, Raw * 4.0), Axis = "Quality"
    | extend Component = "UEBA anomalies",
             Detail = strcat(tostring(Hits), " anomalies / ", tostring(Rules), " rule(s) / summed score ", tostring(round(Raw, 2)))
    | project Principal, Component, Axis, Points, Detail;
//
let Sig_Alert =
    AlertAccounts
    | summarize Raw = sum(toint(SevWeight[AlertSeverity])), Alerts = count(), Rules = dcount(AlertName) by Principal
    | extend Points = min_of(W_Alert, todouble(Raw)), Axis = "Volume"
    | extend Component = "Analytics-rule alerts",
             Detail = strcat(tostring(Alerts), " alerts / ", tostring(Rules), " rule(s) / severity-weighted ", tostring(Raw))
    | project Principal, Component, Axis, Points, Detail;
//
// Tactics arrives in two shapes depending on the source: SecurityAlert emits a
// plain comma-separated string, while Anomalies emits a JSON array serialised
// as a string ("[\"InitialAccess\"]"). Splitting the latter on commas yields a
// single element that still carries its brackets and quotes, which is how
// ["InitialAccess"] ended up rendering as a tactic name. Detect and handle both.
let ExpandTactics = (s: string) {
    iif(s startswith "[", todynamic(s), todynamic(split(s, ",")))
};
let TacticRows =
    union isfuzzy=true
      (AlertAccounts | extend Arr = ExpandTactics(Tactics) | mv-expand T = Arr to typeof(string)
                     | extend Stage = trim(@"[\s""\[\]]+", tostring(T)) | where isnotempty(Stage) | project Principal, Stage),
      (AnomalyEvents | extend Arr = ExpandTactics(Tactics) | mv-expand T = Arr to typeof(string)
                     | extend Stage = trim(@"[\s""\[\]]+", tostring(T)) | where isnotempty(Stage) | project Principal, Stage);
//
let Sig_Breadth =
    TacticRows
    | summarize Stages = dcount(Stage), StageSet = make_set(Stage, 12) by Principal
    | extend Points = min_of(W_Breadth, todouble(Stages - 1) * 7.0), Axis = "Quality"
    | where Points > 0
    | extend Component = "Kill-chain breadth",
             Detail = strcat(tostring(Stages), " distinct MITRE tactics: ", strcat_array(StageSet, ", "))
    | project Principal, Component, Axis, Points, Detail;
//
let Sig_Blast =
    Ident
    | extend Principal = tolower(AccountUPN)
    | where isnotempty(Principal)
    | where "{DeptFilter}" == "*" or Department == "{DeptFilter}"
    | extend RoleCount = array_length(todynamic(AssignedRoles))
    | extend BlastPts = case(tolower(tostring(BlastRadius)) == "high", 8.0,
                             tolower(tostring(BlastRadius)) == "medium", 4.0, 0.0)
    | extend RolePts  = iif(RoleCount > 0, min_of(6.0, todouble(RoleCount) * 2.0), 0.0)
    | extend Points   = min_of(W_Blast, BlastPts + RolePts), Axis = "Impact"
    | where Points > 0
    | extend Component = "Blast radius / privilege",
             Detail = strcat("BlastRadius=", iif(isempty(tostring(BlastRadius)), "n/a", tostring(BlastRadius)),
                             " / ", tostring(RoleCount), " directory role(s)")
    | project Principal, Component, Axis, Points, Detail;
//
let RiskComponents = union isfuzzy=true Sig_Ueba, Sig_Anomaly, Sig_Alert, Sig_Breadth, Sig_Blast;
//
let RiskScores =
    RiskComponents
    | summarize RiskIndex    = round(sum(Points), 1),
                QualityScore = round(sumif(Points, Axis == "Quality"), 1),
                VolumeScore  = round(sumif(Points, Axis == "Volume"), 1),
                ImpactScore  = round(sumif(Points, Axis == "Impact"), 1),
                Contributors = dcount(Component),
                Breakdown    = make_bag(pack(Component, round(Points, 1))),
                Evidence     = make_list(strcat(Component, " -- ", Detail), 10)
        by Principal
    | lookup kind=leftouter (
          Ident
          | project Principal = tolower(AccountUPN), DisplayName = AccountDisplayName,
                    Department, JobTitle, Manager, City, Country,
                    IsEnabled = IsAccountEnabled, UserType, UserState,
                    RoleCount = array_length(todynamic(AssignedRoles))
      ) on Principal
    | extend Department  = iif(isempty(Department), "Unmapped", Department),
             JobTitle    = iif(isempty(JobTitle), "-", JobTitle),             DisplayName = iif(isempty(DisplayName), Principal, DisplayName),
             RoleCount   = coalesce(RoleCount, 0)
    | extend Band = case(RiskIndex >= BandCrit, "Critical",
                         RiskIndex >= BandHigh, "High",
                         RiskIndex >= BandElev, "Elevated",
                                                "Watch")
    | extend BandRank = case(Band == "Critical", 1, Band == "High", 2, Band == "Elevated", 3, 4);
// ===== END RISK MODEL =================================================

// Risk band distribution -- the leadership-safe headline of requirement (2).
// Counts only, no individuals, so it is safe on an executive tab.
RiskScores
| summarize Users = dcount(Principal) by Band, BandRank
| union (
    print Band = "Critical", BandRank = 1, Users = 0
  ) | union (
    print Band = "High",     BandRank = 2, Users = 0
  ) | union (
    print Band = "Elevated", BandRank = 3, Users = 0
  ) | union (
    print Band = "Watch",    BandRank = 4, Users = 0
  )
| summarize Users = sum(Users) by Band, BandRank
| extend Guidance = case(Band == "Critical", "Escalate to insider-risk / IR today",
                         Band == "High",     "Analyst review within SLA",
                         Band == "Elevated", "Corroborate before acting",
                                             "Monitor only -- no action")
| project BandRank, Band, Users, Guidance
| order by BandRank asc

