let InScope = Ident | where Department == "{DeptFilter}" | project Principal = tolower(AccountUPN);
//
let AlertAccounts = materialize(
    SecurityAlert
    | where TimeGenerated {TimeRange}
    // Cheap string prefilter before the expensive expansion. Entities is a
    // string column, so this runs as a substring scan and discards alerts with
    // no account entity before mv-expand multiplies the row count.
    | where Entities has "account"
    | project TimeGenerated, AlertName, AlertSeverity, Tactics, ProductName, ProviderName, Entities
    | extend Ents = todynamic(Entities)
    | mv-expand Ent = Ents
    | where tostring(Ent.Type) =~ "account"
    | extend AcctName = tostring(Ent.Name), UpnSuffix = tostring(Ent.UPNSuffix)
    | where isnotempty(AcctName)
    | extend Principal = tolower(iif(isnotempty(UpnSuffix), strcat(AcctName, "@", UpnSuffix), AcctName))
    | where "{DeptFilter}" == "*" or Principal in (InScope)
    | project Principal, TimeGenerated, AlertName, AlertSeverity, Tactics, ProductName, ProviderName);
//
let AnomalyEvents = materialize(
    Anomalies
    | where TimeGenerated {TimeRange}
    | where RuleStatus == "Production"
    | extend Principal = tolower(coalesce(iif(isempty(UserPrincipalName), '', UserPrincipalName),
                                          iif(isempty(UserName), '', UserName)))
    | where isnotempty(Principal)
    | where "{DeptFilter}" == "*" or Principal in (InScope)
    | project Principal, TimeGenerated, RuleName, Score, Tactics, Techniques, Description);
//
let UebaEvents = materialize(
    BehaviorAnalytics
    | where TimeGenerated {TimeRange}
    | extend Principal = tolower(coalesce(iif(isempty(UserPrincipalName),  '', UserPrincipalName),
                                          iif(isempty(ActorPrincipalName), '', ActorPrincipalName),
                                          iif(isempty(UserName),           '', UserName)))
    | where isnotempty(Principal)
    | where "{DeptFilter}" == "*" or Principal in (InScope)
    | project Principal, TimeGenerated, ActivityType, ActionType, EventSource,
              InvestigationPriority, ActivityInsights, UsersInsights, DevicesInsights,
              SourceIPAddress, SourceIPLocation);
