    UebaEvents
    | summarize Raw = sum(InvestigationPriority), Peak = max(InvestigationPriority), Events = count() by Principal
    | where Raw > 0
    | extend Points = min_of(W_Ueba, Raw / 4.0), Axis = "Quality"
    | extend Component = "UEBA behaviour priority",
             Detail = strcat(tostring(Events), " scored events / cumulative IP ", tostring(Raw), " / peak ", tostring(Peak))
    | project Principal, Component, Axis, Points, Detail;
//
let Sig_Anomaly =
    AnomalyEvents
    | summarize Raw = sum(Score), Rules = dcount(RuleName), Hits = count() by Principal
    | extend Points = min_of(W_Anomaly, Raw * 4.0), Axis = "Quality"
