    union isfuzzy=true
      (AlertAccounts | extend Arr = ExpandTactics(Tactics) | mv-expand T = Arr to typeof(string)
                     | extend Stage = trim(@"[\s""\[\]]+", tostring(T)) | where isnotempty(Stage) | project Principal, Stage),
      (AnomalyEvents | extend Arr = ExpandTactics(Tactics) | mv-expand T = Arr to typeof(string)
                     | extend Stage = trim(@"[\s""\[\]]+", tostring(T)) | where isnotempty(Stage) | project Principal, Stage);
