let Sig_Anomaly =
    AnomalyEvents
    | summarize Raw = sum(Score), Rules = dcount(RuleName), Hits = count() by Principal
    | extend Points = min_of(W_Anomaly, Raw * 4.0), Axis = "Quality"
    | extend Component = "UEBA anomalies",
             Detail = strcat(tostring(Hits), " anomalies / ", tostring(Rules), " rule(s) / summed score ", tostring(round(Raw, 2)))
    | project Principal, Component, Axis, Points, Detail;
//
let Sig_Alert =
    AlertAccounts
    | summarize Raw = sum(toint(SevWeight[AlertSeverity])), Alerts = count(), Rules = dcount(AlertName) by Principal
    | extend Points = min_of(W_Alert, todouble(Raw)), Axis = "Volume"
    | extend Component = "Analytics-rule alerts",
             Detail = strcat(tostring(Alerts), " alerts / ", tostring(Rules), " rule(s) / severity-weighted ", tostring(Raw))
    | project Principal, Component, Axis, Points, Detail;
//
// Tactics arrives in two shapes depending on the source: SecurityAlert emits a
// plain comma-separated string, while Anomalies emits a JSON array serialised
// as a string ("[\"InitialAccess\"]"). Splitting the latter on commas yields a
// single element that still carries its brackets and quotes, which is how
// ["InitialAccess"] ended up rendering as a tactic name. Detect and handle both.
let ExpandTactics = (s: string) {
    iif(s startswith "[", todynamic(s), todynamic(split(s, ",")))
};
let TacticRows =
    union isfuzzy=true
      (AlertAccounts | extend Arr = ExpandTactics(Tactics) | mv-expand T = Arr to typeof(string)
                     | extend Stage = trim(@"[\s""\[\]]+", tostring(T)) | where isnotempty(Stage) | project Principal, Stage),
      (AnomalyEvents | extend Arr = ExpandTactics(Tactics) | mv-expand T = Arr to typeof(string)
                     | extend Stage = trim(@"[\s""\[\]]+", tostring(T)) | where isnotempty(Stage) | project Principal, Stage);
//
let Sig_Breadth =
    TacticRows
    | summarize Stages = dcount(Stage), StageSet = make_set(Stage, 12) by Principal
    | extend Points = min_of(W_Breadth, todouble(Stages - 1) * 7.0), Axis = "Quality"
    | where Points > 0
    | extend Component = "Kill-chain breadth",
             Detail = strcat(tostring(Stages), " distinct MITRE tactics: ", strcat_array(StageSet, ", "))
    | project Principal, Component, Axis, Points, Detail;
//
let Sig_Blast =
    Ident
    | extend Principal = tolower(AccountUPN)
    | where isnotempty(Principal)
    | where "{DeptFilter}" == "*" or Department == "{DeptFilter}"
    | extend RoleCount = array_length(todynamic(AssignedRoles))
    | extend BlastPts = case(tolower(tostring(BlastRadius)) == "high", 8.0,
                             tolower(tostring(BlastRadius)) == "medium", 4.0, 0.0)
    | extend RolePts  = iif(RoleCount > 0, min_of(6.0, todouble(RoleCount) * 2.0), 0.0)
    | extend Points   = min_of(W_Blast, BlastPts + RolePts), Axis = "Impact"
    | where Points > 0
    | extend Component = "Blast radius / privilege",
             Detail = strcat("BlastRadius=", iif(isempty(tostring(BlastRadius)), "n/a", tostring(BlastRadius)),
                             " / ", tostring(RoleCount), " directory role(s)")
    | project Principal, Component, Axis, Points, Detail;
//
let RiskComponents = union isfuzzy=true Sig_Ueba, Sig_Anomaly, Sig_Alert, Sig_Breadth, Sig_Blast;
//
let RiskScores =
    RiskComponents
    | summarize RiskIndex    = round(sum(Points), 1),
                QualityScore = round(sumif(Points, Axis == "Quality"), 1),
                VolumeScore  = round(sumif(Points, Axis == "Volume"), 1),
                ImpactScore  = round(sumif(Points, Axis == "Impact"), 1),
                Contributors = dcount(Component),
                Breakdown    = make_bag(pack(Component, round(Points, 1))),
                Evidence     = make_list(strcat(Component, " -- ", Detail), 10)
        by Principal
    | lookup kind=leftouter (
          Ident
          | project Principal = tolower(AccountUPN), DisplayName = AccountDisplayName,
                    Department, JobTitle, Manager, City, Country,
                    IsEnabled = IsAccountEnabled, UserType, UserState,
                    RoleCount = array_length(todynamic(AssignedRoles))
      ) on Principal
    | extend Department  = iif(isempty(Department), "Unmapped", Department),
             JobTitle    = iif(isempty(JobTitle), "-", JobTitle),             DisplayName = iif(isempty(DisplayName), Principal, DisplayName),
             RoleCount   = coalesce(RoleCount, 0)
    | extend Band = case(RiskIndex >= BandCrit, "Critical",
                         RiskIndex >= BandHigh, "High",
                         RiskIndex >= BandElev, "Elevated",
                                                "Watch")
    | extend BandRank = case(Band == "Critical", 1, Band == "High", 2, Band == "Elevated", 3, 4);
// ===== END RISK MODEL =================================================

// MITRE tactic coverage across the estate. Breadth is the precision driver in
// the model, so showing which tactics are actually represented tells you whether
// the detections cover a chain or just one link of it.
TacticRows
| lookup kind=leftouter (
      Ident | project Principal = tolower(AccountUPN), Department
  ) on Principal
| extend Department = iif(isempty(Department), "Unmapped", Department)
| summarize Users = dcount(Principal), Observations = count() by Tactic = Stage
| extend ChainPosition = case(
      Tactic has_any ("Initial Access", "InitialAccess"),        1,
      Tactic has_any ("Execution"),                              2,
      Tactic has_any ("Persistence"),                            3,
      Tactic has_any ("Privilege Escalation", "PrivilegeEscalation"), 4,
      Tactic has_any ("Defense Evasion", "DefenseEvasion"),      5,
      Tactic has_any ("Credential Access", "CredentialAccess"),  6,
      Tactic has_any ("Discovery"),                              7,
      Tactic has_any ("Lateral Movement", "LateralMovement"),    8,
      Tactic has_any ("Collection"),                             9,
      Tactic has_any ("Command and Control", "CommandAndControl"), 10,
      Tactic has_any ("Exfiltration"),                          11,
      Tactic has_any ("Impact"),                                12,
                                                                99)
| project ChainPosition, Tactic, Users, Observations
| order by ChainPosition asc

// Peer-group deviation. Sentinel UEBA builds peer groups natively in
// UserPeerAnalytics (TF-IDF over group membership, top 20 ranked peers). This
// panel answers "is this person unusual for THEIR team", which is a fairer
// question than "is this person unusual for the bank".
//
// PERFORMANCE: Scored and Ident are both consumed twice (Scored by the peer
// join and the subject join; Ident by the scope filter and the display lookup),
// so both are materialized.
let Ident = materialize(
    IdentityInfo
    | project TimeGenerated, AccountObjectId, AccountUPN, AccountDisplayName, Department
    | summarize arg_max(TimeGenerated, *) by AccountObjectId
    | extend Department = iif(isempty(Department), "Unmapped", Department));
let InScope = Ident | where Department == "{DeptFilter}" | project Principal = tolower(AccountUPN);
let Scoped  = "{DeptFilter}" != "*";
let Scored = materialize(
    BehaviorAnalytics
    | where TimeGenerated {TimeRange}
    | extend Principal = tolower(coalesce(iif(isempty(UserPrincipalName),  '', UserPrincipalName),
                                          iif(isempty(ActorPrincipalName), '', ActorPrincipalName),
                                          iif(isempty(UserName),           '', UserName)))
    | where isnotempty(Principal)
    | summarize UserScore = sum(InvestigationPriority), UserEvents = count() by Principal);
let Peers =
    UserPeerAnalytics
    | project TimeGenerated, UserPrincipalName, PeerUserPrincipalName, Rank
    | summarize arg_max(TimeGenerated, *) by UserPrincipalName, PeerUserPrincipalName
    | project Principal = tolower(UserPrincipalName),
              Peer      = tolower(PeerUserPrincipalName),
              Rank;
Peers
| where not(Scoped) or Principal in (InScope)
| join kind=leftouter (Scored | project Peer = Principal, PeerScore = UserScore) on Peer
| summarize PeerMean = avg(coalesce(todouble(PeerScore), 0.0)),
            PeerMax  = max(coalesce(todouble(PeerScore), 0.0)),
            PeerCount = dcount(Peer)
    by Principal
| join kind=inner Scored on Principal
| extend Deviation = round(todouble(UserScore) - PeerMean, 1)
| extend DeviationRatio = iif(PeerMean > 0, round(todouble(UserScore) / PeerMean, 2), todouble(UserScore))
| lookup kind=leftouter (
      Ident | project Principal = tolower(AccountUPN), DisplayName = AccountDisplayName, Department
  ) on Principal
| extend Subject = iif("{Identify}" == "Named",
                       iif(isempty(DisplayName), Principal, DisplayName),
                       strcat("ANON-", toupper(substring(hash_sha256(Principal), 0, 6))))
| extend Department = iif(isempty(Department), "Unmapped", Department)
| where Deviation > 0
| project Subject, Department, UserScore, PeerMean = round(PeerMean, 1), PeerCount,
          Deviation, DeviationRatio, UserEvents
| order by Deviation desc
| take {TopN}

// Incident pair resolution -- the panel that answers "did it actually find my
// two incidents?" before you try to read a comparison.
//
// ⚠️ PRIORITY SCORE AVAILABILITY
//   priorityScore is NOT a column on SecurityIncident. Verified against a live
//   workspace: the table has 31 columns and none of them is a priority score.
//   The Defender Queue Assistant score lives in the Defender portal and on the
//   Graph security/incidents resource -- it is not synced into Log Analytics.
//
//   This query therefore does two things rather than pretend:
//     1. Probes AdditionalData for a priority-shaped key, because Defender-
//        originated incidents sometimes carry extra properties there. If one is
//        present it is surfaced and banded on Microsoft's published cut-offs
//        (>85 top, 15-85 medium, <15 low).
//     2. Otherwise reports "n/a - Defender portal only" explicitly and exposes
//        a click-through link, rather than showing a blank that reads as zero.
let A = toint("{IncidentA}");
let B = toint("{IncidentB}");
let LookbackDays = 90d;
let Inc =
    SecurityIncident
    | where TimeGenerated > ago(LookbackDays)
    | where IncidentNumber in (A, B)
    | summarize arg_max(TimeGenerated, *) by IncidentNumber
    | extend Side = iif(IncidentNumber == A, "A", "B")
    | extend AD = todynamic(AdditionalData)
    // Probe several spellings; casing of extended properties has varied by
    // provider, and a missing key must not look like a zero score.
    | extend PriorityRaw = coalesce(tostring(AD.priorityScore),
                                    tostring(AD.PriorityScore),
                                    tostring(AD["priority_score"]),
                                    tostring(AD.priority),
                                    "")
    | extend PriorityScore = iif(isempty(PriorityRaw) or PriorityRaw == "null",
                                 int(null), toint(PriorityRaw))
    | extend Priority = case(
          isnull(PriorityScore), "n/a  ·  Defender portal only",
          PriorityScore > 85,    strcat(tostring(PriorityScore), "  ·  Top priority"),
          PriorityScore >= 15,   strcat(tostring(PriorityScore), "  ·  Medium priority"),
                                 strcat(tostring(PriorityScore), "  ·  Low priority"))
    | extend AlertCount = array_length(todynamic(AlertIds))
    | project Side, IncidentNumber, Title, Severity, Priority, Status,
              Classification, CreatedTime, AlertCount, IncidentUrl, Resolved = "Found";
let Missing =
    // datatable literals must be constants, so the requested pair is built with
    // print + union rather than a table literal referencing A and B.
    (print Side = "A", Num = A)
    | union (print Side = "B", Num = B)
    | where Num > 0
    | join kind=leftanti (Inc | project Side) on Side
    | extend IncidentNumber = Num,
             Title = "Not found in the last 90 days — it may be older, or in a different workspace",
             Severity = "-", Priority = "-", Status = "-",
             Classification = "-", CreatedTime = datetime(null), AlertCount = 0,
             IncidentUrl = "", Resolved = "NOT FOUND"
    | project Side, IncidentNumber, Title, Severity, Priority, Status,
              Classification, CreatedTime, AlertCount, IncidentUrl, Resolved;
union Inc, Missing
| extend AlertNote = case(Resolved == "NOT FOUND", "n/a",
                          AlertCount == 0, "No alerts linked — scale and chain factors read zero",
                                           strcat(tostring(AlertCount), " alert(s) linked"))
| project Side, IncidentNumber, Resolved, Severity, Priority, Status, Classification,
          AlertCount, AlertNote, Title, CreatedTime, IncidentUrl
| order by Side asc

// =============================================================================
// Incident priority forensics -- side-by-side factor comparison
// =============================================================================
// Answers the only question that matters when severity and priority disagree:
// "a Medium scored 98 and a High scored 28 -- what caused the difference?"
//
// Microsoft does not publish the weights, so this does NOT try to recompute
// priorityScore. It does something more defensible: it lays out every factor
// Microsoft DOES document as an input, measured on both incidents, side by side.
// The analyst then explains the gap in terms of observable evidence rather than
// in terms of a model nobody outside Redmond can see.
//
// Severity is one of ~11 documented inputs -- not a competitor to the score. A
// Medium scoring 98 means the other ten inputs overwhelmed the severity term.
// =============================================================================
let A = toint("{IncidentA}");
let B = toint("{IncidentB}");
let BaselineDays = 90d;
let LookbackDays = 90d;
//
let Inc = materialize(
    SecurityIncident
    // SecurityIncident is append-only -- one row per update. Bound the scan,
    // then collapse to the latest row per incident before anything else
    // touches it. Without the bound this scans full retention on every render.
    | where TimeGenerated > ago(LookbackDays)
    | where IncidentNumber in (A, B)
    | summarize arg_max(TimeGenerated, *) by IncidentNumber
    | project IncidentNumber, Title, Severity, Status, Classification, ClassificationReason,
              CreatedTime, FirstActivityTime, LastActivityTime, AlertIds, Labels,
              AdditionalData, ProviderName, IncidentUrl);
//
let Side = (n: int) { iif(n == A, "A", "B") };
//
// -- alerts belonging to each incident ---------------------------------------
let IncAlerts = materialize(
    Inc
    | mv-expand AlertId = AlertIds to typeof(string)
    | project IncidentNumber, AlertId
    | join kind=inner (
        SecurityAlert
        | where TimeGenerated > ago(BaselineDays)
        | project SystemAlertId, AlertName, AlertSeverity, Tactics, Techniques,
                  ProviderName, ProductName, ConfidenceScore, Entities, AlertTime = TimeGenerated
      ) on $left.AlertId == $right.SystemAlertId
    | project IncidentNumber, AlertName, AlertSeverity, Tactics, Techniques,
              ProviderName, ProductName, ConfidenceScore, Entities, AlertTime);
//
// -- rule-level rarity and the tenant's own signal-to-noise ------------------
// Microsoft lists "alert types and rarity" and "SnR" as inputs but never defines
// them numerically. These are the customer's own measurable proxies, computed
// from their own history -- which is exactly what makes them defensible.
let RuleStats = materialize(
    SecurityAlert
    | where TimeGenerated > ago(BaselineDays)
    | summarize FiredCount = count(), FirstFired = min(TimeGenerated) by AlertName);
let TotalAlerts = toscalar(RuleStats | summarize sum(FiredCount));
let RuleFp = materialize(
    SecurityIncident
    | where TimeGenerated > ago(BaselineDays)
    | summarize arg_max(TimeGenerated, *) by IncidentNumber
    | where Status == "Closed"
    | mv-expand AlertId = AlertIds to typeof(string)
    | join kind=inner (SecurityAlert | where TimeGenerated > ago(BaselineDays)
                       | project SystemAlertId, AlertName) on $left.AlertId == $right.SystemAlertId
    | summarize ClosedCount = count(),
                FpCount = countif(Classification == "FalsePositive"),
                TpCount = countif(Classification == "TruePositive")
        by AlertName);
//
// -- entity extraction --------------------------------------------------------
let IncEntities = materialize(
    IncAlerts
    | where isnotempty(Entities)
    | extend Ents = todynamic(Entities)
    | mv-expand Ent = Ents
    | extend EntType = tostring(Ent.Type),
             EntName = tolower(coalesce(tostring(Ent.Name), tostring(Ent.HostName),
                                        tostring(Ent.Address), tostring(Ent.FriendlyName)))
    | where isnotempty(EntName)
    | project IncidentNumber, EntType, EntName);
//
// -- privileged / high-blast-radius identities in each incident --------------
let Ident = materialize(
    IdentityInfo
    | project TimeGenerated, AccountObjectId, AccountUPN, AccountName, AccountDisplayName,
              Department, BlastRadius, AssignedRoles
    | summarize arg_max(TimeGenerated, *) by AccountObjectId);
let IncPriv =
    IncEntities
    | where EntType =~ "account"
    | join kind=leftouter (
        Ident
        | extend Key = tolower(coalesce(iif(isempty(AccountUPN), '', AccountUPN),
                                        iif(isempty(AccountName), '', AccountName)))
        | project Key, BlastRadius, RoleCount = array_length(todynamic(AssignedRoles))
      ) on $left.EntName == $right.Key
    | summarize HighBlast = dcountif(EntName, tolower(tostring(BlastRadius)) == "high"),
                Privileged = dcountif(EntName, RoleCount > 0)
        by IncidentNumber;
//
// -- per-incident factor rollup ----------------------------------------------
let Factors =
    Inc
    | join kind=leftouter (
        IncAlerts
        | summarize AlertCount   = count(),
                    DistinctRules= dcount(AlertName),
                    HighSev      = countif(AlertSeverity == "High"),
                    MedSev       = countif(AlertSeverity == "Medium"),
                    Products     = dcount(ProductName),
                    MeanConf     = round(avg(coalesce(ConfidenceScore, 0.0)), 2)
            by IncidentNumber
      ) on IncidentNumber
    | join kind=leftouter (
        IncAlerts
        | mv-expand T = split(Tactics, ",")
        | extend Tac = trim(@"\s+", tostring(T))
        | where isnotempty(Tac)
        | summarize Tactics_n = dcount(Tac), TacticSet = make_set(Tac, 15) by IncidentNumber
      ) on IncidentNumber
    | join kind=leftouter (
        IncAlerts
        | mv-expand K = split(Techniques, ",")
        | extend Tec = trim(@"\s+", tostring(K))
        | where isnotempty(Tec)
        | summarize Techniques_n = dcount(Tec), TechniqueSet = make_set(Tec, 15) by IncidentNumber
      ) on IncidentNumber
    | join kind=leftouter (
        IncEntities
        | summarize Entities_n = dcount(EntName),
                    Accounts_n = dcountif(EntName, EntType =~ "account"),
                    Hosts_n    = dcountif(EntName, EntType =~ "host"),
                    IPs_n      = dcountif(EntName, EntType =~ "ip")
            by IncidentNumber
      ) on IncidentNumber
    | join kind=leftouter IncPriv on IncidentNumber
    | join kind=leftouter (
        IncAlerts
        | join kind=leftouter RuleStats on AlertName
        | join kind=leftouter RuleFp on AlertName
        | summarize RarestRuleFires = min(coalesce(FiredCount, 0)),
                    MeanRuleFires   = round(avg(todouble(coalesce(FiredCount, 0))), 1),
                    WorstFpRate     = round(max(iif(coalesce(ClosedCount, 0) > 0,
                                                    100.0 * FpCount / ClosedCount, 0.0)), 1),
                    MeanFpRate      = round(avg(iif(coalesce(ClosedCount, 0) > 0,
                                                    100.0 * FpCount / ClosedCount, 0.0)), 1)
            by IncidentNumber
      ) on IncidentNumber
    | extend DwellHours = round(datetime_diff('minute', LastActivityTime, FirstActivityTime) / 60.0, 1)
    | extend RarityPct  = iif(TotalAlerts > 0, round(100.0 * todouble(coalesce(MeanRuleFires, 0.0)) / TotalAlerts, 3), 0.0)
    | project IncidentNumber, Title, Severity, Status,
              AlertCount = coalesce(AlertCount, 0), DistinctRules = coalesce(DistinctRules, 0),
              HighSev = coalesce(HighSev, 0), MedSev = coalesce(MedSev, 0),
              Products = coalesce(Products, 0), MeanConf = coalesce(MeanConf, 0.0),
              Tactics_n = coalesce(Tactics_n, 0), TacticSet,
              Techniques_n = coalesce(Techniques_n, 0),
              Entities_n = coalesce(Entities_n, 0), Accounts_n = coalesce(Accounts_n, 0),
              Hosts_n = coalesce(Hosts_n, 0), IPs_n = coalesce(IPs_n, 0),
              HighBlast = coalesce(HighBlast, 0), Privileged = coalesce(Privileged, 0),
              MeanRuleFires = coalesce(MeanRuleFires, 0.0), RarestRuleFires = coalesce(RarestRuleFires, 0),
              MeanFpRate = coalesce(MeanFpRate, 0.0), WorstFpRate = coalesce(WorstFpRate, 0.0),
              DwellHours, RarityPct;
//
// -- pivot into an explainable factor table ----------------------------------
// One row per documented factor, both incidents side by side, with a plain
// reading of which way that factor pushes. This is the artefact you hand to
// whoever asked the question.
let Long =
    Factors
    | extend Bag = pack(
        "01 · Severity (rule author's view of the class)", todouble(case(Severity == "High", 3, Severity == "Medium", 2, Severity == "Low", 1, 0)),
        "02 · Alerts in incident",                          todouble(AlertCount),
        "03 · Distinct detection rules",                    todouble(DistinctRules),
        "04 · High-severity alerts",                        todouble(HighSev),
        "05 · MITRE tactics covered",                       todouble(Tactics_n),
        "06 · MITRE techniques covered",                    todouble(Techniques_n),
        "07 · Distinct products reporting",                 todouble(Products),
        "08 · Entities involved",                           todouble(Entities_n),
        "09 · Accounts involved",                           todouble(Accounts_n),
        "10 · Hosts involved",                              todouble(Hosts_n),
        "11 · High blast-radius identities",                todouble(HighBlast),
        "12 · Privileged identities",                       todouble(Privileged),
        "13 · Rule commonness (mean fires / 90d)",          todouble(MeanRuleFires),
        "14 · Rarity (% of all alert volume)",              RarityPct,
        "15 · Mean false-positive rate of rules (%)",       MeanFpRate,
        "16 · Worst false-positive rate of rules (%)",      WorstFpRate,
        "17 · Mean alert confidence",                       MeanConf,
        "18 · Dwell (hours first to last activity)",        DwellHours)
    | mv-expand Bag
    | extend Factor = tostring(bag_keys(Bag)[0]),
             Value  = todouble(Bag[tostring(bag_keys(Bag)[0])])
    | project IncidentNumber, Factor, Value;
Long
| extend Side = Side(IncidentNumber)
| summarize IncidentA = sumif(Value, Side == "A"), IncidentB = sumif(Value, Side == "B") by Factor
| extend Delta = round(IncidentA - IncidentB, 2)
| extend Favours = case(abs(Delta) < 0.001, "even",
                        Delta > 0,          "A",
                                            "B")
// Direction encodes whether "more" is worse. Noise metrics invert: a high
// false-positive rate and a very common rule push priority DOWN, which is the
// usual explanation for a High-severity incident scoring low.
//
// Text is deliberately terse. The previous wording wrapped to two or three
// lines per row, which is what forced the panel to scroll -- 18 short rows fit
// where 18 wrapped rows do not. A separate Interpretation column repeated this
// text verbatim and has been dropped as redundant.
| extend Direction = case(
      Factor has "false-positive", "▼ lowers — noisy rule",
      Factor has "commonness",     "▼ lowers — common alert",
      Factor has "Rarity",         "▼ lowers — high volume share",
      Factor has "Dwell",          "◆ context only",
                                   "▲ raises priority")
| project Factor, IncidentA, IncidentB, Delta, Favours, Direction
| order by Factor asc

// Investigation Priority distribution -- the evidence panel for Ask 1.
// Shows how BehaviorAnalytics.InvestigationPriority is actually distributed in
// THIS tenant, which is the thing Microsoft does not publish. Anyone arguing
// about what "high" means can read it off this chart.
BehaviorAnalytics
| where TimeGenerated {TimeRange}
| summarize Events = count(), Users = dcount(UserPrincipalName)
    by InvestigationPriority
| extend Priority = toint(InvestigationPriority)
| extend Interpretation = case(Priority == 0, "Benign -- no deviation flagged",
                               Priority <= 3, "Low deviation",
                               Priority <= 6, "Moderate deviation",
                               Priority <= 8, "High deviation",
                                              "Severe deviation")
| project Priority, Interpretation, Events, Users
| order by Priority asc

// Investigation Priority distribution -- the evidence panel for Ask 1.
// Shows how BehaviorAnalytics.InvestigationPriority is actually distributed in
// THIS tenant, which is the thing Microsoft does not publish. Anyone arguing
// about what "high" means can read it off this chart.
BehaviorAnalytics
| where TimeGenerated {TimeRange}
| summarize Events = count(), Users = dcount(UserPrincipalName)
    by InvestigationPriority
| extend Priority = toint(InvestigationPriority)
| extend Interpretation = case(Priority == 0, "Benign -- no deviation flagged",
                               Priority <= 3, "Low deviation",
                               Priority <= 6, "Moderate deviation",
                               Priority <= 8, "High deviation",
                                              "Severe deviation")
| project Priority, Interpretation, Events, Users
| order by Priority asc
